INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N031-03','CN0265','S031-03','身份及规划许可','规划公告','甘肃宏鑫贵源项目年处理2万吨含金属废旧催化剂，建设工程规划许可证620421202400021；与阶段验收转载同项目名、靖远刘川园区对应。','WEB_PRIMARY','公开正文/转载摘录；非原件归档','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N031-04','CN0265','S031-04','厂区规模','项目概况','白银刘川工业集中区，20249m²（约30亩）；办公楼新增1184.94m²。非污水站占地。','WEB_PRIMARY','公开正文/转载摘录；非原件归档','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N031-05','CN0265','S031-05','验收和建设范围','一、六','转载称2025-03-25甘环审发〔2025〕16号批复，2025-04开工，2026-07竣工并调试，2026-08-29阶段性验收组同意通过。2025-11-07危废许可但编号、规模脱敏；验收范围为有色金属及稀有金属综合回收工段与配套环保设施。实际环保投资占总额22.6%，绝对金额被遮蔽，不当废水成本。','WEB_SECONDARY','公开正文/转载摘录；非原件归档','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N031-06','CN0265','S031-05','处理规模、监测及残余物','三（二）（四）（五）、四（二）','生产与生活分别10m³/d；生产化学沉淀/絮凝/芬顿/氨吸收/蒸发回用，生活格栅/厌氧/缺氧/好氧/二沉/MBR/清水池，绿化。验收声称生产出水满足工业直流冷却、洗涤水质，砷六价铬铅镍等一类指标和锌铜等达标，但浓度未公开；生活水绿地灌溉达标。污水沉渣、蒸发析出物、废树脂及隔膜压滤废滤膜等危废委外；废锌镍水洗渣危废管理，废钒钛水洗/压滤渣外售陶瓷等综合利用。1000m³事故池、500m³初雨池非处理量；具体水段称生产不外排，后文泛称达标排放，须核实际排口。','WEB_SECONDARY','公开正文/转载摘录；非原件归档','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N031-07','CN0265','S031-06','废剂处置服务成交单价','采购结果','青海盐湖镁业引进废催化剂处置单位采购结果转载列甘肃宏鑫贵源成交1680元/吨；系外来废剂处置服务价格，非本厂污水/废盐成本或实际已收款。','WEB_SECONDARY','公开正文/转载摘录；非原件归档','2026-11-27');
